import{_ as d,o as e,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Statistics-Positions-and-Labels.md","filePath":"manual-en/CTABLES-Statistics-Positions-and-Labels.md","lastUpdated":1785684581000}'),o={name:"manual-en/CTABLES-Statistics-Positions-and-Labels.md"};function i(r,t,n,c,h,l){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h4 id="_15-7-3-statistics-positions-and-labels" tabindex="-1">15.7.3 Statistics Positions and Labels <a class="header-anchor" href="#_15-7-3-statistics-positions-and-labels" aria-label="Permalink to &quot;15.7.3 Statistics Positions and Labels&quot;">​</a></h4><pre><code>/SLABELS
    [POSITION={COLUMN _|_ ROW _|_ LAYER}]
    [VISIBLE={YES _|_ NO}]
</code></pre><p>The <code>SLABELS</code> subcommand controls the position and visibility of summary statistics for the <code>TABLE</code> subcommand that it follows.</p><p><code>POSITION</code> sets the axis on which summary statistics appear. With <code>POSITION=COLUMN</code>, which is the default, each summary statistic appears in a column. For example:</p><pre><code>CTABLES /TABLE=age [MEAN, MEDIAN] BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Mean</th><th>Median</th><th>Mean</th><th>Median</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>46</td><td>45</td><td>50</td><td>52</td></tr></tbody></table><p>With <code>POSITION=ROW</code>, each summary statistic appears in a row, as shown below:</p><pre><code>CTABLES /TABLE=age [MEAN, MEDIAN] BY gender /SLABELS POSITION=ROW.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>Mean</td><td>46</td><td>50</td></tr><tr><td>Median</td><td>45</td><td>52</td><td></td></tr></tbody></table><p><code>POSITION=LAYER</code> is also available to place each summary statistic in a separate layer.</p><p>Labels for summary statistics are shown by default. Use <code>VISIBLE=NO</code> to suppress them. Because unlabeled data can cause confusion, it should only be considered if the meaning of the data is evident, as in a simple case like this:</p><pre><code>CTABLES /TABLE=ageGroup [TABLEPCT] /SLABELS VISIBLE=NO.
</code></pre><table tabindex="0"><thead><tr><th>Age group</th><th>15 or younger</th><th>.0%</th></tr></thead><tbody><tr><td>16 to 25</td><td>15.7%</td><td></td></tr><tr><td>26 to 35</td><td>13.8%</td><td></td></tr><tr><td>36 to 45</td><td>14.8%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>17.8%</td><td></td></tr><tr><td>66 or older</td><td>21.1%</td><td></td></tr></tbody></table>`,13)])])}const m=d(o,[["render",i]]);export{S as __pageData,m as default};
